// The worker-sast manifests (workers/sast/tools.d) are parsed against REAL
// tool output: the fixtures in testdata/manifests were generated by running
// each manifest's command in the pathos-worker-sast image, offline (docker
// run --network none), on a sample mounted at /work/fixture/src (the
// worker's workspace layout), with the manifest's arguments ({output} a
// file in a mounted /out, {tmp} an empty directory), e.g.
//
//	docker run --rm --network none --entrypoint sh \
//	  -v $PWD/testdata/manifests/sample:/work/fixture/src:ro -v /tmp/out:/out pathos-worker-sast:dev \
//	  -c '/opt/pathos/sast/bin/bandit -r -q -f json -o /out/bandit.json /work/fixture/src;
//	      /opt/pathos/sast/bin/njsscan --sarif -o /out/njsscan.sarif /work/fixture/src;
//	      /opt/pathos/sast/bin/shellcheck-tree /work/fixture/src > /out/shellcheck.jsonl'
//
// Bandit 1.9.4, njsscan 1.0.2 and ShellCheck 0.11.0 ran on
// testdata/manifests/sample. The SAST pack tools ran on
// testdata/manifests/sample-pack: gosec 2.30.0, Flawfinder 2.0.20,
// cppcheck 2.19.0, PHPStan 2.3.6, Psalm 7.11.0, Ruff 0.17.5, ESLint 10.15.0
// with eslint-plugin-security 4.2.1, Semgrep 1.172.0 (PATHOS rules), Bearer
// 2.1.3, TruffleHog 3.99.9, detect-secrets 1.5.0, Kingfisher 2.19.1,
// Talisman 1.37.0, Pylint 4.1.4 and golangci-lint 2.15.0. The credentials in
// sample-pack are fake values made up for the tests.

const sastManifests = "../../../workers/sast/tools.d"

func loadSpec(t *testing.T, file string) PluginDef {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(sastManifests, file))
	if err != nil {
		t.Fatal(err)
	}
	d, err := decodeManifestSpec(raw, true)
	if err != nil {
		t.Fatalf("%s: %v", file, err)
	}
	return d
}

func TestSASTManifestsParseRealOutput(t *testing.T) {
	cases := []struct {
		manifest, fixture, key, category, parser string
		rules                                    []string // rule ids that must be found
		min                                      int
		noLines                                  bool // the tool reports files, not lines (Talisman)
	}{
		// cppcheck reports one memory leak once per return path; the
		// reports are one finding (same rule, file, message and symbol).
		{"bandit.yaml", "bandit.json", "bandit", "sast", "import:bandit", []string{"B602", "B506", "B105", "B404"}, 4, false},
		{"njsscan.yaml", "njsscan.sarif", "njsscan", "sast", "sarif", []string{"eval_nodejs", "generic_os_command_exec", "express_xss"}, 3, false},
		{"shellcheck.yaml", "shellcheck.jsonl", "shellcheck", "code-quality", "jsonmap", []string{"SC2086", "SC2045", "SC2115", "SC2006"}, 5, false},
		// SAST pack (sample-pack).
		{"gosec.yaml", "gosec.json", "gosec", "sast", "import:gosec", []string{"G402", "G701", "G702", "G401", "G202"}, 10, false},
		{"flawfinder.yaml", "flawfinder.csv", "flawfinder", "sast", "import:flawfinder", []string{"FF1014", "FF1001", "FF1016", "FF1044"}, 6, false},
		{"cppcheck.yaml", "cppcheck.xml", "cppcheck", "sast", "import:cppcheck", []string{"arrayIndexOutOfBounds", "getsCalled", "memleak"}, 4, false},
		{"phpstan.yaml", "phpstan.json", "phpstan", "code-quality", "import:phpstan", []string{"function.notFound", "method.notFound", "arguments.count"}, 4, false},
		{"psalm.yaml", "psalm.json", "psalm", "sast", "import:psalm", []string{"TaintedSql", "TaintedHtml", "TaintedShell", "TaintedInclude"}, 5, false},
		{"ruff.yaml", "ruff.json", "ruff", "sast", "import:ruff", []string{"S602", "S307", "S501", "S301", "S324"}, 6, false},
		{"eslint-security.yaml", "eslint-security.json", "eslint-security", "sast", "import:eslint",
			[]string{"security/detect-child-process", "security/detect-eval-with-expression", "security/detect-non-literal-fs-filename", "security/detect-non-literal-require"}, 5, false},
		{"semgrep-ce.yaml", "semgrep-ce.sarif", "semgrep-ce", "sast", "sarif",
			[]string{"pathos.go.tls-insecure-skip-verify", "pathos.python.eval-injection", "pathos.javascript.child-process-exec",
				"pathos.crypto.go.weak-hash", "pathos.database.go.sql-string-concatenation"}, 12, false},
		{"bearer.yaml", "bearer.json", "bearer", "sast", "import:bearer",
			[]string{"go_gosec_sql_concat_sqli", "javascript_lang_eval_user_input", "php_lang_sql_injection", "python_lang_os_command_injection"}, 20, false},
		{"trufflehog.yaml", "trufflehog.jsonl", "trufflehog", "secrets", "import:trufflehog", []string{"Postgres", "MongoDB", "SQLServer"}, 3, false},
		{"detect-secrets.yaml", "detect-secrets.json", "detect-secrets", "secrets", "import:detect-secrets", []string{"Secret Keyword", "Basic Auth Credentials"}, 4, false},
		{"kingfisher.yaml", "kingfisher.json", "kingfisher", "secrets", "import:kingfisher",
			[]string{"betterleaks.mongodb-connection-string", "kingfisher.connection-string.password.unquoted"}, 2, false},
		{"talisman.yaml", "talisman.json", "talisman", "secrets", "import:talisman", []string{"talisman-filename", "talisman-filecontent"}, 6, true},
		{"pylint.yaml", "pylint.json", "pylint", "code-quality", "import:pylint", []string{"eval-used", "bare-except", "missing-timeout", "consider-using-with"}, 6, false},
		{"golangci-lint.yaml", "golangci-lint.json", "golangci-lint", "code-quality", "import:golangci-lint", []string{"errcheck", "G402", "G202"}, 8, false},
	}
	for _, c := range cases {
		t.Run(c.key, func(t *testing.T) {
			d := loadSpec(t, c.manifest)
			if d.Key() != c.key || d.Category != c.category || d.ToolParser().String() != c.parser || !d.FirstParty {
				t.Fatalf("manifest: key %s category %s parser %s", d.Key(), d.Category, d.ToolParser().String())
			}
			if d.Network != "none" || d.Intrusive || !d.RunsOn("") || d.RunsOn("url") {
				t.Errorf("repository tool without network access: %+v", d)
			}
			if d.LicenseSPDX == "" || d.Family != "sast" || len(d.ScanTypes) == 0 {
				t.Errorf("licence, family and scan types are declared: %+v", d)
			}
			sc, _ := scanners.Lookup(c.key)
			if !sc.AdapterAvailable || sc.Family != "sast" || !scanners.ManifestRouted(c.key) {
				t.Errorf("catalog entry: %+v", sc)
			}
			raw, err := os.ReadFile(filepath.Join("testdata", "manifests", c.fixture))
			if err != nil {
				t.Fatal(err)
			}
			fs, err := scanners.ParseToolOutput(d.Key(), d.ToolParser(), raw)
			if err != nil {
				t.Fatalf("parse: %v", err)
			}
			if len(fs) < c.min {
				t.Fatalf("findings: %d, want at least %d", len(fs), c.min)
			}
			var rules []string
			fps := map[string]bool{}
			for _, f := range fs {
				rules = append(rules, f.RuleID)
				// Semgrep CE runs the PATHOS rules, whose rule packs have
				// their own categories (pathos.misconfig.* misconfiguration).
				category := c.category
				if c.key == scanners.SemgrepCE {
					for prefix, cat := range map[string]string{"misconfig": "misconfiguration", "crypto": "crypto", "database": "database", "ai": "ai", "cicd": "cicd"} {
						if strings.HasPrefix(f.RuleID, "pathos."+prefix+".") {
							category = cat
						}
					}
				}
				if f.ScannerKey != c.key || f.Category != category || f.Fingerprint == "" || f.Title == "" {
					t.Errorf("finding: %+v", f)
				}
				if strings.HasPrefix(f.FilePath, "/") || strings.HasPrefix(f.FilePath, "work/") || f.FilePath == "" {
					t.Errorf("repository-relative path: %q", f.FilePath)
				}
				if !c.noLines && (f.StartLine == nil || *f.StartLine <= 0) {
					t.Errorf("line: %+v", f)
				}
				if scanners.SeverityRank(f.Severity) == 0 && f.Severity != "info" {
					t.Errorf("severity %q", f.Severity)
				}
				fps[f.Fingerprint] = true
				// Every finding is found again in the original report.
				loc, err := scanners.LocateToolOutput(d.Key(), d.ToolParser(), raw, f.Fingerprint)
				if err != nil || loc == nil || len(loc.Raw) == 0 {
					t.Errorf("locate %s: %v", f.RuleID, err)
				}
				// Reports parsed with an import parser are stored
				// sanitized (scans.Ingest); findings are found there too.
				if p := d.ToolParser(); p.Kind == "import" {
					if loc, err := scanners.LocateToolOutput(d.Key(), p, scanners.SanitizeImport(p.Format, raw), f.Fingerprint); err != nil || loc == nil {
						t.Errorf("locate %s in the stored report: %v", f.RuleID, err)
					}
				}
			}
			if dup := len(fs) - len(fps); dup != 0 && (c.key != "cppcheck" || dup != 1) {
				t.Errorf("fingerprints are distinct: %d of %d", len(fps), len(fs))
			}
			for _, r := range c.rules {
				if !slices.Contains(rules, r) {
					t.Errorf("rule %s not found in %v", r, rules)
				}
			}
		})
	}
}

func TestShellCheckSeverityMapping(t *testing.T) {
	d := loadSpec(t, "shellcheck.yaml")
	raw, _ := os.ReadFile(filepath.Join("testdata", "manifests", "shellcheck.jsonl"))
	fs, err := scanners.ParseToolOutput(d.Key(), d.ToolParser(), raw)
	if err != nil {
		t.Fatal(err)
	}
	want := map[string]string{"SC2045": "high", "SC2115": "medium", "SC2086": "low", "SC2006": "info"}
	for _, f := range fs {
		if w, ok := want[f.RuleID]; ok && f.Severity != w {
			t.Errorf("%s: severity %s, want %s", f.RuleID, f.Severity, w)
		}
		if f.FilePath != "deploy.sh" {
			t.Errorf("path %q", f.FilePath)
		}
	}
}

func TestOperatorExampleIsValid(t *testing.T) {
	raw, err := os.ReadFile("../../../deploy/scanners.d/example.yaml.disabled")
	if err != nil {
		t.Fatal(err)
	}
	d, err := decodeManifestSpec(raw, false)
	if err != nil || d.Key() != "plugin-sast-semgrep-custom" || d.ToolParser().Kind != "sarif" {
		t.Errorf("example plugin: %v %s", err, d.Key())
	}
}

func TestManifestV2Validation(t *testing.T) {
	base := "name: x\ncategory: dast\ncommand: /bin/true\n"
	for _, c := range []struct {
		body string
		ok   bool
	}{
		{base + "args: [\"{source}\", \"{output}\"]\n", true},
		{base + "targets: [url]\nnetwork: target\nintrusive: true\nargs: [\"-u\", \"{target_url}\", \"-o\", \"{output}\"]\n", true},
		{base + "targets: [api]\nnetwork: target\nargs: [\"--spec\", \"{openapi}\", \"{output}\"]\n", true},
		{base + "targets: [url]\nintrusive: true\nargs: [\"{target_url}\", \"{output}\"]\n", false},    // intrusive needs network: target
		{base + "targets: [repository]\nnetwork: target\nargs: [\"{source}\", \"{output}\"]\n", false}, // target network on a repository tool
		{base + "targets: [url]\nargs: [\"{source}\", \"{output}\"]\n", false},                         // url target without {target_url}
		{base + "targets: [binary]\nargs: [\"{artifact}\", \"{output}\"]\nparser: import:bandit\n", true},
		{base + "args: [\"{source}\", \"{output}\"]\nparser: jsonmap\n", false}, // jsonmap without mapping
		{base + "args: [\"{source}\", \"{output}\"]\nparser: jsonmap\njsonmap: {rule_id: id}\n", true},
		{base + "args: [\"{source}\", \"{output}\"]\ntimeout: 1s\n", false},
		{base + "args: [\"{source}\", \"{output}\"]\nscan_types: [nope]\n", false},
		{base + "args: [\"{source}\", \"{output}\"]\ntargets: [mainframe]\n", false},
		{base + "args: [\"{source}\", \"{output}\"]\nlicense_spdx: \"MIT; rm -rf\"\n", false},
		{"name: x\ncategory: eol\ncommand: /bin/true\nargs: [\"{source}\", \"{output}\"]\n", false},
	} {
		_, err := decodeManifestSpec([]byte(c.body), false)
		if (err == nil) != c.ok {
			t.Errorf("%q: %v", c.body, err)
		}
	}
	// Placeholders take the target's values.
	d, _ := decodeManifestSpec([]byte(base+"targets: [url, api]\nnetwork: target\nargs: [\"{target_url}\", \"{openapi}\", \"{output}\"]\n"), false)
	tool := pluginTool{def: d}
	got := tool.expand(d.Args, RunInput{Out: "/o", TargetFile: "/t/openapi.yaml", Target: &JobTarget{Kind: "api", Reference: "https://a.test"}}, "/tmp/x")
	if strings.Join(got, " ") != "https://a.test /t/openapi.yaml /o" {
		t.Errorf("expand: %v", got)
	}
	if !d.RunsOn("api") || !d.RunsOn("url") || d.RunsOn("") || d.RunsOn("image") {
		t.Error("RunsOn")
	}
	// Intrusive tools skip targets without the intrusive flag.
	d, _ = decodeManifestSpec([]byte(base+"targets: [url]\nnetwork: target\nintrusive: true\nargs: [\"{target_url}\", \"{output}\"]\n"), false)
	if s, _ := (pluginTool{def: d}).Run(context.Background(), RunInput{Out: "/nonexistent/o", Target: &JobTarget{Kind: "url"}}); !strings.Contains(s, "intrusive") {
		t.Errorf("intrusive skip: %q", s)
	}
}

func TestMergeEnv(t *testing.T) {
	got := mergeEnv([]string{"PATH=/bin", "HTTPS_PROXY=http://egress:3128", "https_proxy=http://egress:3128"}, append(append([]string{}, noProxyEnv...), "A=1"))
	if strings.Join(got, ",") != "PATH=/bin,A=1" {
		t.Errorf("proxy variables removed, others kept: %v", got)
	}
}

func TestToolManifestsLoad(t *testing.T) {
	// The shipped manifests load as first-party tools once their commands
	// exist (here: stand-ins in a temporary directory).
	dir := t.TempDir()
	bin := fakeTool(t, dir)
	conf := filepath.Join(dir, "tools.d")
	_ = os.MkdirAll(conf, 0o755)
	entries, _ := os.ReadDir(sastManifests)
	for _, e := range entries {
		raw, _ := os.ReadFile(filepath.Join(sastManifests, e.Name()))
		var cmd string
		for _, l := range strings.Split(string(raw), "\n") {
			if strings.HasPrefix(l, "command: ") {
				cmd = strings.TrimPrefix(l, "command: ")
			}
		}
		_ = os.WriteFile(filepath.Join(conf, e.Name()), []byte(strings.Replace(string(raw), "command: "+cmd, "command: "+bin, 1)), 0o644)
	}
	log := slog.New(slog.NewTextHandler(io.Discard, nil))
	defs := LoadToolManifests(conf, log)
	var keys []string
	for _, d := range defs {
		keys = append(keys, d.Key())
	}
	slices.Sort(keys)
	if !slices.Equal(keys, []string{"bandit", "bearer", "cppcheck", "detect-secrets", "eslint-security", "flawfinder", "golangci-lint", "gosec",
		"kingfisher", "njsscan", "phpstan", "psalm", "pylint", "ruff", "semgrep-ce", "shellcheck", "talisman", "trufflehog"}) {
		t.Fatalf("first-party manifests: %v", keys)
	}
	// The same files are not accepted as operator plugins under catalog
	// keys: an operator plugin's key is always plugin-<category>-<name>.
	for _, d := range LoadPlugins(conf, log) {
		if !strings.HasPrefix(d.Key(), "plugin-") {
			t.Errorf("operator plugin key %s", d.Key())
		}
	}
	// A first-party manifest must name a non-core catalog tool.
	for _, name := range []string{"gitleaks", "not-in-catalog"} {
		body := "name: " + name + "\ncategory: secrets\ncommand: " + bin + "\nargs: [\"{source}\", \"{output}\"]\n"
		if _, err := decodeManifest([]byte(body), true); err == nil {
			t.Errorf("first-party manifest %s accepted", name)
		}
	}
	a := &Agent{plugins: defs}
	if p, ok := a.manifestParser("shellcheck"); !ok || p.Kind != "jsonmap" {
		t.Errorf("manifest parser: %+v %v", p, ok)
	}
	tool := pluginTool{def: defs[0], cacheDir: filepath.Join(dir, "cache")}
	if v, err := tool.Version(context.Background()); err != nil || v == "" {
		t.Errorf("version: %q %v", v, err)
	}
}

// The SAST pack's secrets scanners never contact a provider: verification
// and validation are switched off in every manifest, and the reports keep
// no secret once parsed.
func TestSecretsManifestsAreOffline(t *testing.T) {
	off := map[string]string{"trufflehog.yaml": "--no-verification", "kingfisher.yaml": "--no-validate"}
	for file, flag := range off {
		d := loadSpec(t, file)
		if !slices.Contains(d.Args, flag) || d.Network != "none" {
			t.Errorf("%s: %s and network none: %v %s", file, flag, d.Args, d.Network)
		}
	}
	for _, c := range [][2]string{{"trufflehog.yaml", "trufflehog.jsonl"}, {"kingfisher.yaml", "kingfisher.json"},
		{"talisman.yaml", "talisman.json"}, {"detect-secrets.yaml", "detect-secrets.json"}} {
		d := loadSpec(t, c[0])
		raw, _ := os.ReadFile(filepath.Join("testdata", "manifests", c[1]))
		fs, err := scanners.ParseToolOutput(d.Key(), d.ToolParser(), raw)
		if err != nil {
			t.Fatal(err)
		}
		// The stored copy of the report (SanitizeImport) holds no secret.
		if stored := scanners.SanitizeImport(d.ToolParser().Format, raw); strings.Contains(string(stored), "Fixture-") {
			t.Errorf("%s: secret in the stored report", d.Key())
		}
		for _, f := range fs {
			if strings.Contains(f.Title+f.Description+f.Snippet, "Fixture-") {
				t.Errorf("%s: secret in finding %+v", d.Key(), f)
			}
			loc, err := scanners.LocateToolOutput(d.Key(), d.ToolParser(), raw, f.Fingerprint)
			if err != nil || strings.Contains(string(loc.Raw), "Fixture-") {
				t.Errorf("%s: secret in the located record: %v", d.Key(), err)
			}
		}
	}
}

// Every pack tool runs on repositories only, offline, and is off by
// default; tools whose own configuration could load code (ESLint, Psalm,
// PHPStan, Pylint, golangci-lint, Ruff) are given the image's configuration.
func TestSASTPackManifestPolicy(t *testing.T) {
	entries, _ := os.ReadDir(sastManifests)
	for _, e := range entries {
		d := loadSpec(t, e.Name())
		if d.Network != "none" || d.Intrusive || d.DefaultEnabled || d.RequiresBuild || !slices.Equal(d.Targets, []string{"repository"}) {
			t.Errorf("%s: %+v", e.Name(), d)
		}
		if !strings.HasPrefix(d.Command, "/opt/pathos/sast/") {
			t.Errorf("%s: command %s", e.Name(), d.Command)
		}
	}
	for file, arg := range map[string]string{"phpstan.yaml": "/opt/pathos/sast/config/phpstan.neon", "pylint.yaml": "/opt/pathos/sast/config/pylintrc",
		"ruff.yaml": "--isolated", "semgrep-ce.yaml": "/opt/pathos/rules", "bearer.yaml": "--disable-default-rules"} {
		if d := loadSpec(t, file); !slices.Contains(d.Args, arg) {
			t.Errorf("%s: %s missing from %v", file, arg, d.Args)
		}
	}
}
